set -euo pipefail; T=$(mktemp -d /tmp/f2-parallax-gate.XXXXXX); export T; python3 - <<'PY'
import os, pathlib, json
t=pathlib.Path(os.environ['T'])
anchors=json.load(open('/home/ai-core-node/.claude/star/visual/rig2/augen_anker_exakt.json'))['werte']
html=r'''<!doctype html><meta charset=utf-8><canvas id=c width=1536 height=1024></canvas><script>
const ROOT='file:///home/ai-core-node/.claude/star/visual/';
const rolls=['-25','-20','-15','-10','-05','+00','+05','+10','+15','+20','+25'];
const co=[1,1/3,-1/3,-1];
const anchors=__ANCHORS__;
const cvs=document.getElementById('c'), ctx=cvs.getContext('2d',{willReadFrequently:true});
function img(u){return new Promise((res,rej)=>{let x=new Image();x.onload=()=>res(x);x.onerror=()=>rej(new Error('load '+u));x.src=u})}
function rnum(r){return String(parseInt(r,10));}
function dir(r){return 'kopf_rgba_parallax/gier_+00_nick_+00_roll_'+r+'/'}
async function files(r){let names=['slice_0_front_nase.png','slice_1_mitte_gesicht.png','slice_2_seite_ohren.png','slice_3_hinten_haar.png']; return Promise.all(names.map(n=>img(ROOT+dir(r)+n)))}
async function base(r){return img(ROOT+'kopf_rgba/roll/gier_+00_nick_+00_roll_'+r+'.png')}
function renderBase(im){ctx.globalCompositeOperation='source-over';ctx.clearRect(0,0,1536,1024);ctx.drawImage(im,0,0);return ctx.getImageData(0,0,1536,1024).data.slice()}
function renderSlices(ims,A){ctx.globalCompositeOperation='source-over';ctx.clearRect(0,0,1536,1024);ctx.globalCompositeOperation='lighter';for(let i=0;i<4;i++)ctx.drawImage(ims[i],co[i]*A,0);ctx.globalCompositeOperation='source-over';return ctx.getImageData(0,0,1536,1024).data.slice()}
function lum(d,p){return .2126*d[p]+.7152*d[p+1]+.0722*d[p+2]}
function bilum(d,x,y){let x0=Math.floor(x), x1=Math.min(1535,x0+1), f=x-x0;if(x0<0||x1>1535||y<0||y>1023)return 0;let p0=(y*1536+x0)*4,p1=(y*1536+x1)*4;return lum(d,p0)*(1-f)+lum(d,p1)*f}
function compareDirect(a,b){let sum=0,max=0,n=a.length;for(let i=0;i<n;i++){let d=Math.abs(a[i]-b[i]);sum+=d;if(d>max)max=d}return {rgba_mae:sum/n,rgba_max:max}}
function metrics(ref,v,anchor){let npx=1536*1024,as=0,lost=0,gain=0,inter=0,uni=0,deepHole=0,maxA=0;for(let q=0;q<npx;q++){let p=q*4,a=ref[p+3],b=v[p+3],d=Math.abs(a-b);as+=d;if(d>maxA)maxA=d;let ma=a>=16,mb=b>=16;if(ma&&mb)inter++;if(ma||mb)uni++;if(ma&&!mb)lost++;if(!ma&&mb)gain++;if(a>=64&&b<32)deepHole++}
 let cx=610+(anchor.dx_px||0), cy=207+(anchor.dy_px||0), x0=Math.max(3,Math.round(cx-207)), x1=Math.min(1532,Math.round(cx+207)), y0=Math.max(0,Math.round(cy-113)), y1=Math.min(1023,Math.round(cy+114));
 let best={shift_x:0,mae:1e99};for(let si=-15;si<=15;si++){let s=si*.05,err=0,w=0;for(let y=y0;y<y1;y+=5)for(let x=x0;x<x1;x+=5){let p=(y*1536+x)*4;if(ref[p+3]<16&&v[p+3]<16)continue;err+=Math.abs(lum(v,p)-bilum(ref,x-s,y));w++}let e=err/Math.max(w,1);if(e<best.mae)best={shift_x:+s.toFixed(2),mae:+e.toFixed(4),samples:w}}
 return {alpha_mae:+(as/npx).toFixed(6),alpha_max:maxA,mask_jaccard:+(inter/Math.max(uni,1)).toFixed(8),lost_px:lost,gain_px:gain,deep_hole_px:deepHole,eye_roi_best_shift_x:best.shift_x,eye_roi_mae:best.mae,eye_roi_samples:best.samples};}
(async()=>{try{let out={schema:'PARALLAX_QUANT_GATE/v1',compositor:'Chrome Canvas2D lighter',coefficients:co,amplitudes:[0,.25,.5],rolls:{}};for(const r of rolls){let [b,ss]=await Promise.all([base(r),files(r)]),bd=renderBase(b),z=renderSlices(ss,0),rr={direct_vs_slice0:compareDirect(bd,z),amps:{}};for(const A of [.25,.5]){let vd=renderSlices(ss,A);rr.amps[String(A)]=metrics(z,vd,anchors[rnum(r)])}out.rolls[r]=rr}let worst={};for(const A of ['0.25','0.5']){let rows=Object.entries(out.rolls).map(([r,x])=>[r,x.amps[A]]);worst[A]={max_alpha_mae:Math.max(...rows.map(x=>x[1].alpha_mae)),min_jaccard:Math.min(...rows.map(x=>x[1].mask_jaccard)),max_lost_px:Math.max(...rows.map(x=>x[1].lost_px)),max_gain_px:Math.max(...rows.map(x=>x[1].gain_px)),max_deep_hole_px:Math.max(...rows.map(x=>x[1].deep_hole_px)),max_abs_eye_shift:Math.max(...rows.map(x=>Math.abs(x[1].eye_roi_best_shift_x)))}};out.worst=worst;document.body.innerText='RESULT_JSON '+JSON.stringify(out)}catch(e){document.body.innerText='ERROR '+e.stack}})();
</script>'''.replace('__ANCHORS__',json.dumps(anchors,separators=(',',':')))
(t/'gate.html').write_text(html)
PY
timeout 150 /usr/bin/google-chrome --headless=new --no-sandbox --allow-file-access-from-files --virtual-time-budget=60000 --dump-dom file://$T/gate.html 2>$T/chrome.err | python3 -c 'import sys,re,html; s=sys.stdin.read(); m=re.search(r"RESULT_JSON (\{.*?\})</body>",s,re.S); print(html.unescape(m.group(1)) if m else s[-4000:])'; echo CHROME_ERR_TAIL; tail -30 $T/chrome.err || true; rm -rf $T
